public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    int a = sc.nextInt();
    int[] t = new int[n];
    for (int i = 0; i < n; i++) {
        t[i] = sc.nextInt();
    }
    int currentTime = 0;
    for (int i = 0; i < n; i++) {
        if (t[i] >= currentTime) {
            currentTime = t[i] + a;
        } else {
            currentTime += a;
        }
        System.out.println(currentTime);
    }
}
